local _, ns = ...
local Translate = ns.Lore.Translate

Translate("esES", "skywall", {
	title = "Skywall",
	aliases = { "reino del aire", "plano del aire" },
	sections = {
		{
			title = "Resumen",
			text = [=[Skywall es el reino del aire, uno de los cuatro dominios del Plano Elemental. Es un cielo sin fin de tormentas y corrientes, sin suelo debajo ni techo encima. Su señor es {link:al-akir}Al'Akir{/link}, el Señor del Viento, y sus hijos nativos son los espíritus y elementales del viento. Para la mayoría de los pueblos de {link:azeroth}Azeroth{/link}, Skywall es solo un nombre en el saber de los chamanes. Para los {link:skyborne}Skyborne{/link} ha sido su hogar durante diez mil años.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los señores elementales asolaron en otro tiempo el mundo joven. En la primera era sirvieron a los Dioses Antiguos, y cuando los servidores de los titanes quebraron aquel imperio oscuro, los elementales fueron expulsados del mundo y encerrados en un reino aparte. A cada señor se le dio su propio dominio. El aire le correspondió a {link:al-akir}Al'Akir{/link}. Desde entonces el viento de Skywall sopla más allá de la vista de los mortales, y pocos de los que entraron en él han vuelto para contarlo.]=],
		},
		{
			title = "Las islas ocultas",
			text = [=[En las largas eras que siguieron a la {link:war-of-the-ancients}Guerra de los Ancestros{/link}, unos elfos que huían de Eldre'Thalas hallaron refugio en Skywall. Los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link} alzaron su tierra hasta el cielo y la situaron en un rincón tranquilo del reino, donde no llegaba la mirada del {link:al-akir}Señor del Viento{/link}. Allí los {link:skyborne}shen'dorei{/link} construyeron un puñado de provincias insulares. {link:zephras-isle}Zephras Isle{/link} era una de ellas. Anvilas y Siroccas, con sus poblados de Shen'dramar y Nueva Eldre'naar, eran otras. Antaño, unas corrientes de viento llamadas skystreams llevaban a los viajeros de isla en isla. Esos caminos llevan mucho tiempo cerrados.]=],
		},
		{
			title = "El presente",
			text = [=[El refugio ha fallado. Los espíritus que guardaban las islas desaparecieron hace mucho, y los {link:anchor-pylons}pilones de anclaje{/link} que sujetaban {link:zephras-isle}Zephras{/link} en su lugar eran también las salvaguardas que la ocultaban. Esas salvaguardas han caído. Un señor del viento del este ha visto la isla con sus propios ojos, y ha prometido que {link:al-akir}Al'Akir{/link} sabrá de ella. Ningún {link:skyborne}shen'dorei{/link} puede decir cuándo se volverá hacia ellos el Señor del Viento. Todos saben que lo hará.]=],
		},
	},
})

Translate("esES", "zephras-isle", {
	title = "Zephras Isle",
	aliases = { "Zephras" },
	sections = {
		{
			title = "Resumen",
			text = [=[Zephras Isle flota en {link:skywall}Skywall{/link}, el reino del aire, lejos de cualquier costa de {link:azeroth}Azeroth{/link}. Es el hogar de los {link:skyborne}Skyborne{/link}, los elfos que se llaman a sí mismos shen'dorei. Grandes árboles se alzan sobre sus arboledas del norte, tierras altas azules se extienden por su centro, y en su borde sudeste se levanta el puerto de {link:valanaar}Valanaar{/link}. Sus acantilados vierten cascadas al cielo abierto. Durante diez mil años la isla fue un refugio oculto. Ahora se está desmoronando, y su pueblo ha empezado a mirar hacia abajo, hacia un mundo del que huyeron sus antepasados.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los {link:skyborne}shen'dorei{/link} descienden de rebeldes de Eldre'Thalas, la ciudad Altonato de {link:feralas}Feralas{/link} que hoy se llama {red:dire-maul}La Masacre{/red}. Se alzaron contra el príncipe {red:tortheldrin}Tortheldrin{/red}, perdieron su guerra y huyeron al oeste a través del mar. Cuando las naves del príncipe les dieron alcance, los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link} alzaron un gran pedazo de tierra hasta el cielo y lo sacaron del mundo. Lo anclaron en {link:skywall}Skywall{/link} con antiguos pilones, y allí los exiliados construyeron una civilización pequeña y luminosa entre las nubes. Su fundador, el rebelde enmascarado llamado el {link:flight-from-eldre-thalas}Shal'nan{/link}, cedió más tarde su poder a un consejo elegido por el pueblo.]=],
		},
		{
			title = "El presente",
			text = [=[Hace varios siglos, los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link} desaparecieron sin decir palabra. Desde entonces los pilones se han debilitado, y barrios enteros se han desmoronado hacia el cielo. {link:ruins-of-ban-aethal}Ban'aethal{/link} cayó en una sola noche. Se ha perdido el contacto con las otras islas de los {link:skyborne}shen'dorei{/link}, y los refugiados que llegaron a Zephras se hacinan ahora en {link:valanaar}Valanaar{/link} o se dan al bandidaje. En medio de ese miedo llegaron los {link:al-aketh}Al'Aketh{/link}, un culto de {link:al-akir}Al'Akir{/link} dirigido por la suma sacerdotisa {link:high-priestess-lorthuna}Lorthuna{/link}. Tomaron {link:falaath-village}Falaath Village{/link} y el {link:shrine-of-akir}Shrine of Akir{/link}, y atacaron las atalayas de los pilones. Su propósito era romper las salvaguardas que ocultaban la isla. Los {link:windshapers}Windshapers{/link} y la {link:high-order}High Order{/link} se desprecian mutuamente, pero se unieron a los {link:peacekeepers}Peacekeepers{/link} de {link:valennia-stormfist}Valennia Stormfist{/link} contra el culto, y el culto fue quebrado. Su obra no. Las salvaguardas han desaparecido, y un señor de la hueste del Señor del Viento ha visto Zephras. Ahora cada orden envía a sus jóvenes a {link:azeroth}Azeroth{/link}: los Windshapers, al {link:earthen-ring}Anillo de la Tierra{/link} en {link:mulgore}Mulgore{/link}; la High Order, al {link:kirin-tor}Kirin Tor{/link} de {link:city-of-dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}El Consejo de Ancianos.{/b} El Anciano Supremo {link:talaanis-shadowsong}Talaanis Shadowsong{/link} dirige el consejo de la isla desde {link:valanaar}Valanaar{/link}.
• {b}Los {link:windshapers}Windshapers{/link}.{/b} Chamanes y videntes que guardan las piedras sagradas y buscan a los espíritus perdidos.
• {b}La {link:high-order}High Order{/link}.{/b} Magisters de sangre Altonato que quieren dominar por sí mismos la magia de la isla.
• {b}Los {link:peacekeepers}Peacekeepers{/link}.{/b} La milicia de la isla, lo más parecido a un ejército que tienen los {link:skyborne}shen'dorei{/link}.
• {b}Los {link:al-aketh}Al'Aketh{/link}.{/b} Fanáticos del {link:al-akir}Señor del Viento{/link}, dispersos pero no destruidos.
• {b}Los Nightclaw.{/b} Un círculo secreto de druidas en el {link:shadowgale-forest}Shadowgale Forest{/link}.
• {b}Bestias.{/b} Vuldren, ursera, prideclaws, hipogrifos y shrieklings, muchos de ellos vueltos salvajes desde que los vientos callaron.]=],
		},
		{
			title = "Tradiciones de la isla",
			text = [=[• Un {link:skyborne}shen'dorei{/link} que alcanza la mayoría de edad recibe una reliquia familiar que llevó antes otro que lo precedió. Cuando muere su portador, la reliquia se recupera para el siguiente joven.
• Los muertos son quemados, y sus cenizas se entregan a los vientos.
• Las piedras de viento, gemas azules llenas del viento en bruto, iluminan y calientan hoy la mayoría de los hogares de la isla.
• Pequeños cristales de recuerdo guardan voces. Al tocarlos, dejan que una grabación flote débilmente en el aire.]=],
		},
	},
})

Translate("esES", "thendal-village", {
	title = "Thendal Village",
	aliases = { "Thendal Grove" },
	sections = {
		{
			title = "Resumen",
			text = [=[Thendal Village se encuentra en las arboledas del norte de {link:zephras-isle}Zephras{/link}, donde los jóvenes {link:skyborne}shen'dorei{/link} alcanzan la mayoría de edad. Sus casas están construidas en torno y dentro de un inmenso gran árbol padre, y sus forestales mantienen el equilibrio de los bosques. {link:rorian-the-dayseeker}Rorian the Dayseeker{/link} dirige la aldea. Ancianos del consejo acuden aquí para juzgar a los jóvenes y enviarlos a recorrer la isla. Al este de la aldea se alzan las Thendal Standing Stones, un lugar de viento y de líneas ley. Subiendo por un paso al nordeste se halla el Rise of Spirits, donde los novicios {link:windshapers}Windshapers{/link} beben la sagrada sapta. Los ursera tienen su guarida en una cueva al sur. Últimamente el culto ha llegado incluso hasta aquí.]=],
		},
	},
})

Translate("esES", "shen-dar-village", {
	title = "Shen'dar Village",
	sections = {
		{
			title = "Resumen",
			text = [=[Shen'dar Village es el primer poblado al sur de las arboledas del norte, situado en las colinas azules de las {link:shen-dar-highlands}Shen'dar Highlands{/link}. La alguacil {link:constable-aonda}Aonda{/link} mantiene su paz con muy pocos {link:peacekeepers}Peacekeepers{/link}. Ambas órdenes tienen ancianos aquí: {link:illaya-amberwind}Illaya Amberwind{/link} por los {link:windshapers}Windshapers{/link} y {link:rathiril-sunlance}Rathiril Sunlance{/link} por la {link:high-order}High Order{/link}, y no están de acuerdo en casi nada. Coriella Calmbreeze regenta la posada. Durante un tiempo el poblado toleró a una misionera {link:al-aketh}Al'Aketh{/link} en sus calles. Esa paz terminó cuando el culto se reunió en Falaath para atacar el poblado, y los aldeanos golpearon primero.]=],
		},
	},
})

Translate("esES", "shen-dar-highlands", {
	title = "Shen'dar Highlands",
	sections = {
		{
			title = "Resumen",
			text = [=[Las Shen'dar Highlands son el corazón ondulado de {link:zephras-isle}Zephras{/link}. Sus piedras erguidas son sagradas para los {link:windshapers}Windshapers{/link}, que las guardan de los curiosos magisters de la {link:high-order}High Order{/link}. Se ha derramado sangre entre las dos órdenes junto a esas piedras. Hay bandidos escondidos en una cueva tras una cascada al norte, los hipogrifos anidan al sur y los prideclaws merodean cerca del poblado. En una colina cerca del pilón de las tierras altas vive Kuramaa, un viejo y travieso espíritu del bosque. La vuldren alada Vulgara caza en las colinas, y los {link:peacekeepers}Peacekeepers{/link} han puesto precio a su cabeza.]=],
		},
	},
})

Translate("esES", "falaath-village", {
	title = "Falaath Village",
	sections = {
		{
			title = "Resumen",
			text = [=[Falaath Village yace en ruinas en las {link:shen-dar-highlands}Shen'dar Highlands{/link}, y los {link:al-aketh}Al'Aketh{/link} lo han hecho suyo. Unos misioneros reciben a los nuevos conversos en su puerta y los marcan con el signo de Akir. Entre sus casas derruidas toman forma tormentas, invocadas por los clamatormentas del culto. Fue en la posada de Falaath donde el sacerdote celeste {link:skypriest-aanders}Aanders{/link} recibió en secreto a la suma sacerdotisa {link:high-priestess-lorthuna}Lorthuna{/link}, y allí el culto planeó sus dos golpes gemelos contra {link:shen-dar-village}Shen'dar Village{/link} y la {link:west-pylon-watchtower}atalaya occidental{/link}. El comandante Cyclas debía dirigir el primero. No vivió para hacerlo.]=],
		},
	},
})

Translate("esES", "windsong-lake", {
	title = "Windsong Lake",
	sections = {
		{
			title = "Resumen",
			text = [=[Windsong Lake se encuentra en el centro de {link:zephras-isle}Zephras{/link}, entre las tierras altas y el santuario. Unos cangrejos llamados windsong crawlers viven en sus orillas y en los ríos que lo alimentan, y en ningún otro lugar del mundo. Solo pueden capturarse unas pocas semanas al año. Antaño los crawlers eran un manjar que se llevaba a las otras islas de los {link:skyborne}shen'dorei{/link}. Unos ensamblajes regalados por los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link} solían rastrear {link:the-loch}el lago{/link}. Cuando los pilones empezaron a fallar, muchos de ellos se hundieron hasta su lecho, y algunos siguen allí.]=],
		},
	},
})

Translate("esES", "west-pylon-watchtower", {
	title = "West Pylon Watchtower",
	aliases = { "atalaya occidental" },
	sections = {
		{
			title = "Resumen",
			text = [=[La West Pylon Watchtower guarda uno de los {link:anchor-pylons}pilones de anclaje{/link} en el borde sudoeste de las {link:shen-dar-highlands}Shen'dar Highlands{/link}. Los {link:peacekeepers}Peacekeepers{/link} la defendieron hasta que llegaron los {link:al-aketh}Al'Aketh{/link}. El sacerdote celeste {link:skypriest-aanders}Aanders{/link} dirigió el ataque, y los defensores murieron en su puesto. Entre ellos estaba el sobrino del Anciano Supremo {link:talaanis-shadowsong}Talaanis Shadowsong{/link}, cuyo sello familiar se encontró en la torre. No consta lo que el sacerdote celeste le hizo allí al pilón. El Consejo solo supo que el culto había venido a por la torre, y no a por los soldados que había en ella.]=],
		},
	},
})

Translate("esES", "valanaar", {
	title = "Valanaar",
	sections = {
		{
			title = "Resumen",
			text = [=[Valanaar es el puerto y la ciudad principal de {link:zephras-isle}Zephras Isle{/link}, construida en el borde sudeste de la isla. El Anciano Supremo {link:talaanis-shadowsong}Talaanis Shadowsong{/link} celebra consejo aquí, y {link:valennia-stormfist}Valennia Stormfist{/link} dirige a los {link:peacekeepers}Peacekeepers{/link} desde la misma sala. Los {link:windshapers}Windshapers{/link} tienen una logia cerca del centro de la ciudad, y la {link:high-order}High Order{/link} tiene otra en su extremo sudeste. La capitana prohíbe las luchas abiertas entre ellos en sus calles. Los refugiados de {link:ruins-of-ban-aethal}Ban'aethal{/link} esperan noticias en la ciudad. Desde los Valanaar Skydocks, los navíos skycutter surcan ahora los planos hacia {link:azeroth}Azeroth{/link}: uno rumbo a {link:mulgore}Mulgore{/link}, el otro rumbo a {link:city-of-dalaran}Dalaran{/link}.]=],
		},
	},
})

Translate("esES", "gustberry-lowlands", {
	title = "Gustberry Lowlands",
	aliases = { "Gustberry Fields" },
	sections = {
		{
			title = "Resumen",
			text = [=[Las Gustberry Lowlands son las tierras de cultivo que rodean {link:valanaar}Valanaar{/link}, ricas en huertos y campos abiertos. Flutterflies gigantes revolotean sobre ellas, y los galestriders saquean la cosecha. Salteadores de caminos mantienen pequeños campamentos en las colinas. Los shrieklings de una cueva al oeste de la ciudad se han vuelto osados, y un erudito de la {link:high-order}High Order{/link} estuvo a punto de morir entre ellos. Cuando los {link:al-aketh}Al'Aketh{/link} marcharon contra el pilón oriental, las tierras bajas se convirtieron en campo de batalla, y los sanadores y matones del culto llenaron los campos al norte de la ciudad. En el borde de la isla, al oeste de Valanaar, los {link:windshapers}Windshapers{/link} guardan un Santuario de las Llamas oculto.]=],
		},
	},
})

Translate("esES", "east-pylon-watchtower", {
	title = "East Pylon Watchtower",
	aliases = { "atalaya oriental" },
	sections = {
		{
			title = "Resumen",
			text = [=[La East Pylon Watchtower se alza justo a las afueras de {link:valanaar}Valanaar{/link} y guarda el {link:anchor-pylons}pilón de anclaje{/link} más cercano a la ciudad. Los {link:al-aketh}Al'Aketh{/link} la atacaron con todas sus fuerzas, dirigidos por la comandante {link:commander-belguilos}Belguilos{/link}, una antigua {link:peacekeepers}Peacekeeper{/link} a la que el culto llama la Quebrantadora. {link:yorana-windyreed}Yorana Windyreed{/link} trajo una fuerza de socorro desde la ciudad y resistió, aunque esperaba morir allí. Cuando cayó Belguilos, el ataque se deshizo. El Consejo vio que el culto había golpeado por igual las torres occidental y oriental, y comprendió por fin que su objetivo eran los propios pilones.]=],
		},
	},
})

Translate("esES", "windfield-orchard", {
	title = "Windfield Orchard",
	sections = {
		{
			title = "Resumen",
			text = [=[En el Windfield Orchard crecen manzanas de tormenta, en las tierras bajas al oeste de {link:valanaar}Valanaar{/link}. Pertenece a Alvarion y {link:aamelia-windfield}Aamelia Windfield{/link}. Una banda de bandidos a las órdenes de Ferauu the Bludgeon se llevaba por la fuerza una parte de cada cosecha. Cuando Alvarion resultó gravemente herido, fue a la ciudad a contratar ayuda, mientras su esposa se quedaba a defender sus árboles. En el huerto se alza también un viejo ensamblaje ciclónico de los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link}, roto y murmurante. Hace una y otra vez la misma pregunta: ¿cuál es su propósito?]=],
		},
	},
})

Translate("esES", "shrine-of-akir", {
	title = "Shrine of Akir",
	sections = {
		{
			title = "Resumen",
			text = [=[El Shrine of Akir se alza al norte de {link:valanaar}Valanaar{/link}, por encima de los campos y cascadas del este de la isla. Es la fortaleza de los {link:al-aketh}Al'Aketh{/link} y la sede de la suma sacerdotisa {link:high-priestess-lorthuna}Lorthuna{/link}. Aquí vino el magister de la {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan Brightwish{/link} a hablar de paz, y aquí murió. Aquí también dirigió {link:valennia-stormfist}Valennia Stormfist{/link} a los {link:peacekeepers}Peacekeepers{/link}, los {link:windshapers}Windshapers{/link} y la High Order en su asalto. Sus combatientes golpearon por el frente mientras ella guiaba a las órdenes por el flanco hasta el sanctasanctórum. Muchos cayeron en ambos bandos. Lorthuna huyó por un portal a las agujas que hay encima.]=],
		},
	},
})

Translate("esES", "rohashi-spires", {
	title = "Rohashi Spires",
	sections = {
		{
			title = "Resumen",
			text = [=[Las Rohashi Spires flotan en el cielo abierto sobre el {link:shrine-of-akir}Shrine of Akir{/link}, y solo se llega a ellas por un portal desde el santuario. Aquí resistió {link:high-priestess-lorthuna}Lorthuna{/link} por última vez. No había venido a romper las salvaguardas, porque ya estaban rotas. Había venido a encender una baliza. Le respondió {link:rohash}Rohash{/link}, el {link:al-akir}Señor del Viento{/link} del Este. Por un momento los elfos se alzaron solos contra la hueste del Señor del Viento. Entonces llegaron los chamanes del {link:earthen-ring}Anillo de la Tierra{/link} y los magos del {link:kirin-tor}Kirin Tor{/link}, y las agujas se convirtieron en el lugar donde los {link:skyborne}Skyborne{/link} conocieron a sus nuevos aliados.]=],
		},
	},
})

Translate("esES", "shadowgale-forest", {
	title = "Shadowgale Forest",
	aliases = { "Shadowgale" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Shadowgale Forest cubre el nordeste de {link:zephras-isle}Zephras{/link}, y la mayoría de los {link:skyborne}shen'dorei{/link} lo creen embrujado. No se equivocan. Unos pálidos {link:vanishing-of-the-wind-spirits}espíritus del viento{/link} llamados hollows vagan entre sus árboles, y aparecieron por primera vez después de que se desvanecieran los espíritus del viento. El culto suele evitar el bosque, un temor que sus druidas alimentan con gusto. En una cueva al nordeste, los druidas Nightclaw tienen su guarida. Los {link:al-aketh}Al'Aketh{/link} cayeron sobre ella sin aviso, guiados por uno de los propios druidas. Entre los árboles vive también un ermitaño que lleva años sin hablar con nadie.]=],
		},
	},
})

Translate("esES", "ruins-of-ban-aethal", {
	title = "Ruins of Ban'aethal",
	aliases = { "Ban'aethal" },
	sections = {
		{
			title = "Resumen",
			text = [=[Ban'aethal era una aldea en lo profundo del {link:shadowgale-forest}Shadowgale Forest{/link}, en el borde nordeste de la isla. Una noche, sin aviso, el suelo bajo ella empezó a caer hacia el cielo. Sus habitantes huyeron con lo que pudieron cargar y ahora esperan en {link:valanaar}Valanaar{/link}. Algunos volvieron a por sus pertenencias y no regresaron. Entre las ruinas se reúnen espíritus fantasmales que entonan un canto extraño y triste, como si estuvieran atados al lugar. Se dice que allí yace dormido un gran dragón elemental.]=],
		},
	},
})

Translate("esES", "talaanis-shadowsong", {
	title = "Talaanis Shadowsong",
	subtitle = "Anciano Supremo de Zephras Isle",
	found = "La sala del consejo de Valanaar",
	hint = [=[Busque al Anciano Supremo en la sala del consejo de Valanaar.]=],
	allegiance = "Consejo de Ancianos · Zephras Isle",
	aliases = { "Anciano Supremo Shadowsong" },
	sections = {
		{
			title = "Resumen",
			text = [=[Talaanis Shadowsong es el Anciano Supremo de {link:zephras-isle}Zephras Isle{/link} y el jefe de su Consejo de Ancianos. Gobierna desde {link:valanaar}Valanaar{/link}, junto a la capitana de los {link:peacekeepers}Peacekeepers{/link}. No pertenece ni a los {link:windshapers}Windshapers{/link} ni a la {link:high-order}High Order{/link}, y debe mantener unido a un pueblo dispuesto a despedazarse. Quienes le sirven lo llaman un buen hombre. Aun en estos años duros, el pueblo de la isla lo ama.]=],
		},
		{
			title = "Importancia",
			text = [=[Talaanis está al frente del viejo orden que dejó el {link:flight-from-eldre-thalas}Shal'nan{/link}: un consejo elegido por los propios {link:skyborne}shen'dorei{/link}. En su tiempo ese orden ha sido puesto a prueba como nunca antes. Los espíritus se han ido, los pilones fallan, un culto del {link:al-akir}Señor del Viento{/link} domina media isla, y las dos grandes órdenes de su pueblo apenas se dirigen la palabra. Fue en su sala donde se descubrió el verdadero propósito del culto, y fue su bendición la que envió a los jóvenes de {link:zephras-isle}Zephras{/link} hacia {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirige {link:shadow-council}el Consejo{/link} de Ancianos desde {link:valanaar}Valanaar{/link}.
• Pasó a los {link:peacekeepers}Peacekeepers{/link} una pista sobre el culto: un desertor {link:al-aketh}Al'Aketh{/link} que deseaba cambiar de bando.
• Escuchó el cristal de recuerdo que reveló el plan de {link:high-priestess-lorthuna}Lorthuna{/link}.
• Bendijo las expediciones de ambas órdenes a {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de la vida de Talaanis antes de estos días. Ninguna crónica registra cuánto tiempo lleva siendo Anciano Supremo, ni quién era su sobrino.]=],
		},
	},
	chapters = {
		{
			title = "El sello de los Shadowsong",
			hint = "Lleve al Anciano Supremo noticias de la atalaya occidental.",
			text = [=[Los defensores de la {link:west-pylon-watchtower}atalaya occidental{/link} murieron en su puesto. Entre los muertos estaba el sobrino del Anciano Supremo, y su sello familiar volvió a {link:valanaar}Valanaar{/link} en la mano de un desconocido. Talaanis recibió el anillo y la noticia con entereza. Luego hizo lo que debe hacer un anciano en tales días. Envió a quien se lo había traído a los {link:peacekeepers}Peacekeepers{/link}, porque la isla necesitaba cada espada dispuesta.]=],
		},
		{
			title = "El cristal de recuerdo",
			hint = "Lleve al Anciano Supremo lo que llevaba el desertor.",
			text = [=[El desertor murió antes de poder hablar, pero bajo su cuerpo había un cristal de recuerdo dañado. Talaanis hizo que {link:valennia-stormfist}Valennia{/link} lo despertara. De él brotaron voces rotas: {link:high-priestess-lorthuna}Lorthuna{/link}, hablando de los pilones y de salvaguardas que debían caer. Valennia recordó que el {link:flight-from-eldre-thalas}Shal'nan{/link} había dicho una vez que los pilones eran salvaguardas además de anclas, escudos contra cualquier otra cosa que habitara en {link:skywall}Skywall{/link}. Talaanis lo comprendió al instante. El culto pretendía abrir la isla a su {link:al-akir}Señor del Viento{/link}.]=],
		},
		{
			title = "El destino de Zephras",
			hint = "Cuente al Anciano Supremo lo que se supo en las agujas.",
			text = [=[Después de las agujas, los líderes de ambas órdenes acudieron a Talaanis con la misma sombría noticia. Las salvaguardas habían desaparecido, y la isla quedaba expuesta a {link:al-akir}Al'Akir{/link} en su propio reino. Cada orden pensaba buscar su respuesta en {link:azeroth}Azeroth{/link}, y Talaanis dio a ambas su bendición. Esperaba que lo que encontraran diera a {link:zephras-isle}Zephras{/link} la estabilidad que le faltaba desde hacía años.]=],
		},
	},
	mentions = {
		{ text = "La petición del Anciano Supremo" },
		{ text = "El desertor" },
		{ text = "Noticias desafortunadas" },
		{ text = "Tiempos desesperados" },
		{
			text = [=[Lo que viene después, la despedida de la {link:horde}Horda{/link}]=],
		},
		{
			text = [=[Lo que viene después, la despedida de la {link:alliance}Alianza{/link}]=],
		},
	},
	bonds = {
		{ id = "valennia-stormfist", name = "Valennia Stormfist", note = "capitana de sus Peacekeepers" },
		{ id = "aetheen-of-the-gales", name = "Aetheen of the Gales", note = "del mismo consejo" },
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "Gran Vidente Celeste de los Windshapers" },
		{ id = "elaadrin-evengale", name = "Elaadrin Evengale", note = "Magister Supremo de la High Order" },
		{ id = "high-priestess-lorthuna", name = "Suma Sacerdotisa Lorthuna", note = "quiso abrir su isla al Señor del Viento" },
	},
})

Translate("esES", "elaadrin-evengale", {
	title = "Elaadrin Evengale",
	subtitle = "Magister Supremo de la High Order",
	found = "La logia de la High Order, al sudeste de Valanaar",
	hint = [=[Busque al Magister Supremo en la logia de la High Order, en el extremo de Valanaar.]=],
	allegiance = "High Order · Alianza",
	aliases = { "Elaadrin" },
	sections = {
		{
			title = "Resumen",
			text = [=[Elaadrin Evengale es el Magister Supremo de la {link:high-order}High Order{/link}, los magisters de sangre Altonato de {link:zephras-isle}Zephras Isle{/link}. Desde su logia de {link:valanaar}Valanaar{/link} dirige a quienes creen que los {link:skyborne}shen'dorei{/link} confiaron demasiado en sus protectores elementales. Es orgulloso, de lengua afilada y está seguro de su camino. Bajo su mando, la High Order ha encontrado un paso a través de los planos hasta {link:azeroth}Azeroth{/link}, y un nuevo aliado allí.]=],
		},
		{
			title = "Importancia",
			text = [=[Elaadrin cree que los dones de los espíritus desaparecidos pueden igualarse con la antigua magia de los {red:highborne}Altonato{/red}, si su pueblo logra aprenderla de nuevo. Esa magia se ha debilitado en {link:skywall}Skywall{/link}. Por eso miró hacia fuera. Sus magisters abrieron una especie de cerradura a través de los planos y se asomaron al mundo que sus antepasados habían dejado, y alguien al otro lado les devolvió la mirada: el {link:kirin-tor}Kirin Tor{/link} de {link:city-of-dalaran}Dalaran{/link}. Gracias a él, la {link:high-order}High Order{/link} se ha unido a la {link:alliance}Alianza{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirige la {link:high-order}High Order{/link} desde su logia de {link:valanaar}Valanaar{/link}.
• Envió al magister {link:belathaan-brightwish}Belathaan Brightwish{/link} al {link:shrine-of-akir}Shrine of Akir{/link} para buscar la paz con el culto.
• Estudió la magia de las piedras sagradas de los {link:windshapers}Windshapers{/link} contra la voluntad de estos.
• Mandó llamar al {link:kirin-tor}Kirin Tor{/link} cuando se planeó el asalto al santuario.
• Se mantuvo junto a {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link} frente a {link:high-priestess-lorthuna}Lorthuna{/link} en las {link:rohashi-spires}Rohashi Spires{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La cerradura",
			hint = "Escuche los planes del Magister Supremo para la High Order.",
			text = [=[Elaadrin contó a los jóvenes de su orden lo que la cerradura le había mostrado. La tierra de la que había huido su pueblo era solo una parte de un vasto mundo que ahora se llama {link:azeroth}Azeroth{/link}. Sus magos habían encontrado amigos allí, una orden muy parecida a la suya. Algunos {link:skyborne}shen'dorei{/link}, dijo, debían dejar {link:skywall}Skywall{/link}, recuperar lo que sus antepasados habían perdido y traerlo a casa para salvar la isla.]=],
		},
		{
			title = "La lengua plateada",
			hint = [=[Responda al Magister Supremo cuando se conozca el destino de su enviado.]=],
			text = [=[Cuando el culto recurrió por primera vez a la violencia, Elaadrin había aconsejado negociar. Envió a su amigo {link:belathaan-brightwish}Belathaan{/link} al santuario. A {link:valanaar}Valanaar{/link} volvió una caja con la lengua de Belathaan, pintada de plata. Elaadrin no quiso más diálogo. Ofreció a los {link:peacekeepers}Peacekeepers{/link} todo el apoyo de la {link:high-order}High Order{/link}.]=],
		},
		{
			title = "En el ojo de la tormenta",
			hint = [=[Permanezca junto al Magister Supremo en las agujas sobre el santuario.]=],
			text = [=[En las agujas, Elaadrin ofreció a {link:high-priestess-lorthuna}Lorthuna{/link} una muerte rápida si se rendía. Ella se rió de él. Cuando llegó el servidor del {link:al-akir}Señor del Viento{/link}, Elaadrin tenía poco con qué responder salvo su valor, hasta que llegaron los magos del {link:kirin-tor}Kirin Tor{/link} y saludó por primera vez al archimago {link:archmage-ansirem-runeweaver}Ansirem Runeweaver{/link}.]=],
		},
		{
			title = "El skycutter a Dalaran",
			hint = "Embárquese en Valanaar rumbo a la ciudad de los magos.",
			text = [=[Elaadrin había querido ser el primero de su pueblo en pisar {link:azeroth}Azeroth{/link}. El culto cambió sus planes. Por ahora se queda en {link:valanaar}Valanaar{/link}, y envía por delante a los jóvenes magisters a {link:city-of-dalaran}Dalaran{/link}, donde uno de sus magos espera para recibirlos.]=],
		},
	},
	mentions = {
		{ text = "El Magister Supremo" },
		{ text = "Atrapar el viento" },
		{ text = "Al servicio de {link:zephras-isle}Zephras{/link}" },
		{ text = "La misión de Fillion" },
		{ text = "El destino de {link:zephras-isle}Zephras{/link}" },
		{ text = "Lo que viene después" },
	},
	bonds = {
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "su rival, por ahora su aliada" },
		{ id = "belathaan-brightwish", name = "Belathaan Brightwish", note = "su amigo y enviado" },
		{ id = "rathiril-sunlance", name = "Rathiril Sunlance", note = "anciano de su orden en Shen'dar" },
		{ id = "valennia-stormfist", name = "Valennia Stormfist", note = "la capitana a la que aceptó seguir" },
		{ id = "high-priestess-lorthuna", name = "Suma Sacerdotisa Lorthuna", note = "la sacerdotisa contra la que luchó en las agujas" },
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "Anciano Supremo de Zephras Isle" },
	},
})

Translate("esES", "ayessa-dawnsinger", {
	title = "Ayessa Dawnsinger",
	subtitle = "Gran Vidente Celeste de los Windshapers",
	found = "La logia de los Windshapers, en el centro de Valanaar",
	hint = [=[Busque a la Gran Vidente Celeste en la logia de los Windshapers de Valanaar.]=],
	allegiance = "Windshapers · Horda",
	aliases = { "Ayessa", "Gran Vidente Celeste" },
	sections = {
		{
			title = "Resumen",
			text = [=[Ayessa Dawnsinger es la Gran Vidente Celeste de los {link:windshapers}Windshapers{/link}, los chamanes y videntes de {link:zephras-isle}Zephras Isle{/link}. Es fiera, orgullosa y de enfado fácil, y guarda con celo su título y los lugares sagrados de su orden. Cree que su pueblo debe llamar de vuelta a sus espíritus perdidos, y en su búsqueda encontró al {link:earthen-ring}Anillo de la Tierra{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Ayessa es la voz de los {link:skyborne}shen'dorei{/link} que aún guardan fe a los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link}. No niega la crisis. Dice abiertamente que los {link:windshapers}Windshapers{/link} quizá compartan la culpa de la partida de los espíritus, y llama a los {link:al-aketh}Al'Aketh{/link} un reflejo oscuro de su propia orden. Buscando por los planos con su vista celeste, dio con chamanes de {link:azeroth}Azeroth{/link} cuya vista alcanzaba más allá de los cielos. Por medio de {link:muln-earthfury}Muln Earthfury{/link}, los Windshapers llegaron al Anillo, y por medio del Anillo, a la {link:horde}Horda{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirige a los {link:windshapers}Windshapers{/link} desde su logia de {link:valanaar}Valanaar{/link}.
• Envió a un novicio a castigar al magister de la {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan{/link} por entrometerse con los ensamblajes de los espíritus.
• Exige sangre por sangre cuando matan a los Windshapers.
• Mandó llamar al {link:earthen-ring}Anillo de la Tierra{/link} antes del asalto al santuario.
• Se enfrentó a {link:high-priestess-lorthuna}Lorthuna{/link}, antigua hermana suya en la orden, en las {link:rohashi-spires}Rohashi Spires{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Una gran aventura",
			hint = [=[Escuche el plan de la Gran Vidente Celeste para los Windshapers.]=],
			text = [=[Ayessa contó a los jóvenes {link:windshapers}Windshapers{/link} lo que había encontrado. La cuna de su pueblo, {link:kalimdor}Kalimdor{/link}, formaba ahora parte de un mundo mucho mayor. Sus chamanes eran más poderosos que cualquiera de {link:zephras-isle}Zephras{/link}, y su conocimiento de los planos podría salvar la isla. Pidió a jóvenes {link:skyborne}shen'dorei{/link} fuertes que se unieran a una expedición hacia ellos.]=],
		},
		{
			title = "El ensamblaje roto",
			hint = "Averigüe quién robó las piezas del ensamblaje de Valanaar.",
			text = [=[Uno de los últimos ensamblajes que aún funcionaban en {link:valanaar}Valanaar{/link} apareció despojado de sus componentes. El rastro llevó al magister de la {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan Brightwish{/link}. Para Ayessa era la prueba de la arrogancia de la que llevaba tiempo acusando a los magisters. Mandó decir que solo respondería a las amenazas de la High Order cuando su líder acudiera a ella en persona.]=],
		},
		{
			title = "Mi antigua hermana",
			hint = [=[Permanezca junto a la Gran Vidente Celeste en las agujas sobre el santuario.]=],
			text = [=[En las agujas, Ayessa suplicó a {link:high-priestess-lorthuna}Lorthuna{/link} que se detuviera, advirtiéndole que romper las salvaguardas podía condenarlos a todos. Lorthuna se burló de ella llamándola hermana caída que andaba en compañía de la {link:high-order}High Order{/link}. Cuando llegó el {link:al-akir}Señor del Viento{/link} del Este, {link:muln-earthfury}Muln Earthfury{/link} apareció con los chamanes del Anillo. Ayessa lo conoció en mitad de una batalla.]=],
		},
		{
			title = "La vanguardia",
			hint = [=[Embárquese en Valanaar rumbo a la tierra del Anillo de la Tierra.]=],
			text = [=[Ayessa había querido ir ella misma a {link:azeroth}Azeroth{/link}. El culto la retuvo en {link:valanaar}Valanaar{/link}. En su lugar envía por delante a un puñado de jóvenes {link:windshapers}Windshapers{/link} como su vanguardia, a {link:mulgore}Mulgore{/link}, donde espera {link:alaana-stormwalker}Alaana Stormwalker{/link}. Ha jurado que su pueblo encontrará la manera de salvar su hogar.]=],
		},
	},
	mentions = {
		{ text = "La Gran Vidente Celeste" },
		{ text = "Una respuesta firme" },
		{ text = "Sangre por sangre" },
		{ text = "Al servicio de {link:zephras-isle}Zephras{/link}" },
		{ text = "El destino de {link:zephras-isle}Zephras{/link}" },
		{ text = "Lo que viene después" },
	},
	bonds = {
		{ id = "muln-earthfury", name = "Muln Earthfury", note = "chamán del Anillo de la Tierra que le respondió" },
		{ id = "elaadrin-evengale", name = "Elaadrin Evengale", note = "su rival, por ahora su aliado" },
		{ id = "high-priestess-lorthuna", name = "Suma Sacerdotisa Lorthuna", note = "antigua hermana suya en los Windshapers" },
		{ id = "illaya-amberwind", name = "Illaya Amberwind", note = "anciana de su orden en Shen'dar" },
		{ id = "alaana-stormwalker", name = "Alaana Stormwalker", note = "espera a su vanguardia en Mulgore" },
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "Anciano Supremo de Zephras Isle" },
	},
})

Translate("esES", "al-akir", {
	title = "Al'Akir",
	subtitle = "El Señor del Viento, señor de Skywall",
	found = "En algún lugar de las tormentas sin fin de Skywall",
	allegiance = "El Plano Elemental",
	aliases = { "Al'Akir el Señor del Viento", "Señor del Viento" },
	sections = {
		{
			title = "Resumen",
			text = [=[Al'Akir, el Señor del Viento, es el señor del aire y el amo de {link:skywall}Skywall{/link}. Es uno de los cuatro grandes señores elementales, par de Ragnaros del fuego, Neptulon de las mareas y Therazane de la piedra. El viento y la tormenta son sus servidores, y los elementales del aire son su hueste. Ninguna crónica mortal habla de nadie que haya estado ante él y regresado.]=],
		},
		{
			title = "Importancia",
			text = [=[Para los {link:elements}señores elementales{/link}, los pueblos mortales importan poco. El Señor del Viento no sabía que los {link:skyborne}shen'dorei{/link} existían. Durante diez mil años, espíritus de su propio reino ocultaron {link:zephras-isle}Zephras Isle{/link} a su vista tras las salvaguardas de sus pilones, y los elfos crecieron en su dominio sin conocerlo. Los espíritus que los criaron no pronunciaban su nombre. Cuando los elfos preguntaban, los espíritus se inquietaban, desviaban la pregunta y les decían que no tenían nada que temer en sus islas. Algunos shen'dorei llegaron a dudar de que fuera real. Otros, mirando a través del plano con su vista celeste, vislumbraron su poder y empezaron a adorarlo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• En la primera era del mundo, él y los demás señores elementales sirvieron a los Dioses Antiguos, hasta que los servidores de los titanes encerraron a los elementales en un reino aparte.
• Gobierna {link:skywall}Skywall{/link} con una hueste de elementales del aire y señores de los vientos.
• Su nombre es adorado por los {link:al-aketh}Al'Aketh{/link}, que se llaman a sí mismos sus fieles.
• Sus misioneros advierten que quien se acerque a sus fieles con falsos pretextos sentirá su ira.
• Su servidor {link:rohash}Rohash{/link} se jacta de que los ejércitos del Señor del Viento no tienen fin en Skywall.
• El miedo a su llegada empuja hoy a ambas órdenes de los {link:skyborne}shen'dorei{/link} a buscar ayuda en {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de esta era describe el rostro del Señor del Viento, su trono en {link:skywall}Skywall{/link} ni su voluntad. Los {link:skyborne}shen'dorei{/link} solo lo conocen por el silencio de sus espíritus y las jactancias de sus servidores.]=],
		},
	},
	chapters = {
		{
			title = "La mirada del Señor del Viento",
			hint = [=[Averigüe lo que el Anillo de la Tierra y el Kirin Tor contaron a las órdenes sobre el Señor del Viento.]=],
			text = [=[Cuando {link:high-priestess-lorthuna}Lorthuna{/link} encendió su baliza en las {link:rohashi-spires}Rohashi Spires{/link}, {link:rohash}Rohash{/link}, el Señor del Viento del Este, respondió. Le asombró que pudiera existir un lugar así en el reino del Señor del Viento, y elogió a sus «hermanos descarriados» por haberlo ocultado tan bien. Prometió que su señor sabría de ello. Los chamanes del {link:earthen-ring}Anillo de la Tierra{/link} y los magos del {link:kirin-tor}Kirin Tor{/link} contaron a los elfos lo que sabían de los señores elementales. Lo que oyeron dio a los líderes de ambas órdenes buenas razones para tener miedo. En su propio dominio, Al'Akir podía destruirlos cuando quisiera.]=],
		},
	},
	mentions = {
		{
			text = [=[El siguiente paso, donde un anciano lo nombra supuesto soberano de {link:skywall}Skywall{/link}]=],
		},
		{
			text = [=[{link:falaath-village}Falaath Village{/link}, la llamada del culto a servirle]=],
		},
	},
	bonds = {
		{ id = "rohash", name = "Rohash", note = "Señor del Viento del Este, su servidor" },
		{ id = "high-priestess-lorthuna", name = "Suma Sacerdotisa Lorthuna", note = "encendió una baliza en su nombre" },
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "teme su juicio" },
	},
})

Translate("esES", "valennia-stormfist", {
	title = "Valennia Stormfist",
	subtitle = "Capitana de los Peacekeepers",
	found = "La sala del consejo de Valanaar",
	hint = [=[Busque a la capitana de los Peacekeepers en la sala del consejo de Valanaar.]=],
	allegiance = "Peacekeepers · Zephras Isle",
	aliases = { "Valennia" },
	sections = {
		{
			title = "Resumen",
			text = [=[Valennia Stormfist es la capitana de los {link:peacekeepers}Peacekeepers{/link}, la milicia de {link:zephras-isle}Zephras Isle{/link}. Mantiene el orden en {link:valanaar}Valanaar{/link} y prohíbe a los {link:windshapers}Windshapers{/link} y a la {link:high-order}High Order{/link} pelear en sus calles. Es directa y práctica. Durante mucho tiempo sus Peacekeepers evitaron la guerra abierta con el culto. Cuando eso dejó de ser posible, ella fue quien planeó la guerra.]=],
		},
		{
			title = "Importancia",
			text = [=[Valennia se interpone entre las dos órdenes enfrentadas de la isla y el culto que amenaza a ambas. Vio que los {link:windshapers}Windshapers{/link} y la {link:high-order}High Order{/link} nunca se unirían el uno por el otro. Podían unirse contra un enemigo mayor. Su plan para el asalto al {link:shrine-of-akir}Shrine of Akir{/link}, preparado mucho antes de que hiciera falta, llevó a las tres fuerzas juntas al campo de batalla.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirige a los {link:peacekeepers}Peacekeepers{/link} desde {link:valanaar}Valanaar{/link}.
• Envió refuerzos a la {link:east-pylon-watchtower}atalaya oriental{/link} cuando el culto la atacó.
• Despertó el cristal de recuerdo del desertor y recordó que los pilones eran también salvaguardas.
• Consiguió el apoyo de ambas órdenes para el asalto al santuario.
• Irrumpió en el sanctasanctórum del {link:shrine-of-akir}Shrine of Akir{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Tiempos desesperados",
			hint = "Lleve el plan de la capitana a los líderes de ambas órdenes.",
			text = [=[El culto dominaba gran parte de la isla y creía vencidos a los {link:peacekeepers}Peacekeepers{/link}. Valennia quiso usar ese orgullo en su contra. Una distracción en la entrada del santuario, y una pequeña fuerza de Peacekeepers, {link:windshapers}Windshapers{/link} y magisters subiendo por el flanco, podrían llegar al sanctasanctórum y acabar allí con {link:high-priestess-lorthuna}Lorthuna{/link}. Ambas órdenes aceptaron. Ninguna perdonó a la otra.]=],
		},
		{
			title = "El sanctasanctórum",
			hint = [=[Siga a las fuerzas de la capitana hasta el corazón del santuario.]=],
