Translate("esES", "aetheen-of-the-gales", {
	title = "Aetheen of the Gales",
	subtitle = "Anciana de Zephras Isle",
	found = "Thendal Village",
	hint = [=[Busque a la anciana del consejo que vigila a los jóvenes en Thendal Village.]=],
	allegiance = "Consejo de Ancianos · Zephras Isle",
	aliases = { "Aetheen" },
	sections = {
		{
			title = "Resumen",
			text = [=[Aetheen of the Gales es miembro del Consejo de Ancianos de {link:zephras-isle}Zephras Isle{/link}. Ha venido a {link:thendal-village}Thendal Village{/link} a leer el flujo de los vientos en la arboleda y a juzgar a los jóvenes {link:skyborne}shen'dorei{/link} que alcanzan allí la mayoría de edad. Observa antes de hablar. Cuando un joven la conoce, ella ya sabe mucho de él.]=],
		},
		{
			title = "Importancia",
			text = [=[Aetheen es el ojo del consejo sobre la nueva generación. En un tiempo en que la isla necesita todas las manos capaces, decide cuáles de los jóvenes están listos para dejar el amparo de la arboleda. Es también de las primeras en nombrarles el peligro con claridad: los {link:al-aketh}Al'Aketh{/link}, fanáticos de un «supuesto» soberano de {link:skywall}Skywall{/link}, cuyo poder y ambiciones crecen cada día.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Lee los vientos de {link:thendal-village}Thendal Grove{/link} para el consejo.
• Pone a prueba a los jóvenes enviándolos contra los ursera y su madre de camada.
• Los envía al sur, ante la alguacil {link:constable-aonda}Aonda{/link} en {link:shen-dar-village}Shen'dar Village{/link}, a la que amenaza el culto.
• Envía a otros a aprender los caminos de la naturaleza con un trotamundos cerca de Shen'dar.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de la vida de Aetheen antes de estos días. No consta si pertenece a alguna de las órdenes, ni cuánto tiempo lleva en el consejo.]=],
		},
	},
	chapters = {
		{
			title = "El siguiente paso",
			hint = "Supere la prueba de la anciana y vaya adonde ella le envíe.",
			text = [=[En las cuevas al sur de la arboleda, los ursera se habían vuelto hambrientos y desesperados, guiados por una madre de camada a la que los forestales llamaban Urs'anah. Aetheen envió allí al joven como prueba de su determinación. Superada la prueba, no lo elogió por mucho tiempo. Lo envió al sur, donde el culto acosaba {link:shen-dar-village}Shen'dar Village{/link}, y le dijo que contara que ella lo enviaba.]=],
		},
	},
	mentions = {
		{ text = "Aetheen of the Gales" },
		{ text = "Matriarca inmunda" },
		{ text = "El aventurero" },
	},
	bonds = {
		{ id = "rorian-the-dayseeker", name = "Rorian the Dayseeker", note = "le envía a los jóvenes" },
		{ id = "constable-aonda", name = "Alguacil Aonda", note = "una buena mujer, en sus palabras" },
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "Anciano Supremo de su consejo" },
	},
})

Translate("esES", "high-priestess-lorthuna", {
	title = "Suma Sacerdotisa Lorthuna",
	subtitle = "Suma sacerdotisa de los Al'Aketh",
	found = "El Shrine of Akir y las agujas que hay sobre él",
	hint = [=[Enfréntese a la suma sacerdotisa del culto del Señor del Viento.]=],
	allegiance = "Al'Aketh",
	aliases = { "Lorthuna" },
	sections = {
		{
			title = "Resumen",
			text = [=[La suma sacerdotisa Lorthuna dirige a los {link:al-aketh}Al'Aketh{/link}, el culto de {link:al-akir}Al'Akir{/link} en {link:zephras-isle}Zephras Isle{/link}. Fue en otro tiempo {link:windshapers}Windshaper{/link} y hermana de la orden de {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link}. Ahora gobierna el {link:shrine-of-akir}Shrine of Akir{/link} y habla de una gran obra que traerá al Señor del Viento hasta su pueblo. Es fría, astuta y cruel, y sus seguidores se llaman a sí mismos los instrumentos de su voluntad.]=],
		},
		{
			title = "Importancia",
			text = [=[Lorthuna vio lo que el resto de su pueblo no veía: que los pilones de {link:zephras-isle}Zephras{/link} eran salvaguardas además de anclas. Convirtió ese secreto en un arma. Su culto tomó {link:falaath-village}Falaath Village{/link}, atacó las atalayas de los pilones e hizo caer las salvaguardas. Fuera cual fuera su destino, su obra no puede deshacerse. Zephras yace ahora expuesta ante su {link:al-akir}Señor del Viento{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Envió asaltantes y predicadores por toda la isla desde el {link:shrine-of-akir}Shrine of Akir{/link}.
• Se reunió con el sacerdote celeste {link:skypriest-aanders}Aanders{/link} en Falaath y puso en marcha sus ataques contra Shen'dar y la {link:west-pylon-watchtower}atalaya occidental{/link}.
• Hizo matar al enviado de la {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan Brightwish{/link} y devolvió su lengua a {link:valanaar}Valanaar{/link}.
• Encendió una baliza en las {link:rohashi-spires}Rohashi Spires{/link} para los servidores del {link:al-akir}Señor del Viento{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La invitada de Falaath",
			hint = "Averigüe lo que planea el culto para las Shen'dar Highlands.",
			text = [=[A un recluta que se infiltró entre los fieles de Falaath se le dijo que se mantuviera lejos de la posada, donde el sacerdote celeste recibía a una invitada. La invitada era Lorthuna. Sus órdenes fueron breves. Tenía otros asuntos, y esto era solo una pieza de su juego. {link:skypriest-aanders}Aanders{/link} tomaría la {link:west-pylon-watchtower}atalaya occidental{/link}, y Cyclas tomaría {link:shen-dar-village}Shen'dar Village{/link}.]=],
		},
		{
			title = "La baliza",
			hint = [=[Siga a la suma sacerdotisa hasta las agujas sobre su santuario.]=],
			text = [=[En las agujas, Lorthuna dijo a sus enemigos que llegaban demasiado tarde. Las salvaguardas llevaban días caídas. Estaba encendiendo una baliza. Cuando llegó el {link:al-akir}Señor del Viento{/link} del Este, lo saludó y le pidió que la llevara ante el Señor del Viento como heraldo de su gloria. {link:rohash}Rohash{/link} la apartó de un golpe y la lanzó volando al cielo sin fin.]=],
		},
	},
	mentions = {
		{ text = "Matones {link:al-aketh}Al'Aketh{/link}" },
		{ text = "Vengado diez veces" },
		{ text = "Los verdaderos planes del culto" },
	},
	bonds = {
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "su antigua hermana" },
		{ id = "skypriest-aanders", name = "Sacerdote Celeste Aanders", note = "su servidor en Falaath" },
		{ id = "belathaan-brightwish", name = "Belathaan Brightwish", note = "el enviado al que mató" },
		{ id = "rohash", name = "Rohash", note = "respondió a su baliza" },
		{ id = "al-akir", name = "Al'Akir", note = "el señor al que servía" },
	},
})

Translate("esES", "rohash", {
	title = "Rohash",
	subtitle = "Señor del Viento del Este",
	found = "Las Rohashi Spires, sobre el Shrine of Akir",
	hint = [=[Enfréntese al señor del viento que respondió a la baliza del culto.]=],
	allegiance = "Al'Akir · Skywall",
	sections = {
		{
			title = "Resumen",
			text = [=[Rohash es el Señor del Viento del Este, uno de los grandes señores del aire que sirven a {link:al-akir}Al'Akir{/link} en {link:skywall}Skywall{/link}. Es poderoso, burlón y se deleita con el sufrimiento de los seres inferiores. Llegó a {link:zephras-isle}Zephras Isle{/link} cuando lo llamó la baliza de {link:high-priestess-lorthuna}Lorthuna{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Rohash es el primer servidor del {link:al-akir}Señor del Viento{/link} del que se sabe que ha visto {link:zephras-isle}Zephras Isle{/link}. Nunca había oído hablar de la isla ni de su pueblo. Su descubrimiento lo asombró, y comprendió al instante lo que significaba. Los espíritus que habían dado refugio a los elfos eran sus propios «hermanos descarriados», y habían ocultado bien la isla. Sin las salvaguardas, podía llevar el secreto a su señor.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Respondió a la baliza de {link:high-priestess-lorthuna}Lorthuna{/link} en las {link:rohashi-spires}Rohashi Spires{/link}.
• Apartó a la suma sacerdotisa cuando ella se atrevió a darle órdenes.
• Invocó a los ejércitos del {link:al-akir}Señor del Viento{/link} contra los elfos.
• Se retiró cuando el {link:earthen-ring}Anillo de la Tierra{/link} y el {link:kirin-tor}Kirin Tor{/link} se pusieron del lado de los {link:skyborne}shen'dorei{/link}.
• Se burló de la esperanza de los elfos de resistir, diciendo que los ejércitos de su señor no tenían fin en aquel reino.]=],
		},
	},
	chapters = {
		{
			title = "El Señor del Viento del Este",
			hint = "Esté en las agujas cuando la baliza reciba respuesta.",
			text = [=[Rohash se rió de los elfos y de los amigos que habían encontrado en lugares bajos. Se preguntó en voz alta si su señor los esclavizaría o simplemente los devoraría. Cuando {link:muln-earthfury}Muln Earthfury{/link} le dijo que el Anillo no tenía nada contra él, Rohash decidió marcharse. Antes de irse, hizo a los elfos su promesa. Eran huéspedes en el reino de su señor solo hasta que llegara el juicio del {link:al-akir}Señor del Viento{/link}. No sabrían cuándo llegaría, pero llegaría.]=],
		},
	},
	mentions = {
		{ text = "Enfrentarse a {link:high-priestess-lorthuna}Lorthuna{/link}" },
	},
	bonds = {
		{ id = "al-akir", name = "Al'Akir", note = "su señor" },
		{ id = "high-priestess-lorthuna", name = "Suma Sacerdotisa Lorthuna", note = "encendió la baliza a la que respondió" },
		{ id = "muln-earthfury", name = "Muln Earthfury", note = "habló ante él en nombre del Anillo de la Tierra" },
	},
})

