Translate("esES", "windshapers", {
	title = "Windshapers",
	aliases = { "Windshaper" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Windshapers son los chamanes y videntes de los {link:skyborne}Skyborne{/link}. Descienden de los primeros shen'dorei que recibieron de los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link} el don de la vista celeste, el poder de ver a través del plano elemental. Durante eras fueron los guías espirituales de {link:zephras-isle}Zephras Isle{/link}. Guardan sus sagradas piedras erguidas y cuidan los ensamblajes e instrumentos que dejaron los espíritus.]=],
		},
		{
			title = "Su credo",
			text = [=[Los Windshapers sostienen que su pueblo tiene con los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link} una deuda que nunca podrá saldarse del todo. Han jurado encontrar a los espíritus y restaurar las antiguas costumbres. Sin los espíritus, dicen, están casi ciegos a lo que ocurre en {link:skywall}Skywall{/link}. Algunos temen que la culpa de la partida de los espíritus sea suya. Desconfían de la {link:high-order}High Order{/link}, a la que llaman arrogantes herederos de los Altonato que buscan dominar lo que deberían honrar. Donde la High Order ve un don en las líneas ley surgidas, los Windshapers ven heridas en la tierra.]=],
		},
		{
			title = "En el presente",
			text = [=[Su magia se ha desvanecido desde que se fueron los espíritus, y hay sangre entre ellos y la {link:high-order}High Order{/link}. Su líder, la {link:ayessa-dawnsinger}Gran Vidente Celeste{/link} Ayessa Dawnsinger, buscó por los planos con su vista celeste y encontró al {link:earthen-ring}Anillo de la Tierra{/link} de {link:azeroth}Azeroth{/link}. Por medio del Anillo, los Windshapers se han unido a la {link:horde}Horda{/link}. Su vanguardia zarpa ahora de {link:valanaar}Valanaar{/link} rumbo a {link:mulgore}Mulgore{/link}.]=],
		},
	},
})

Translate("esES", "high-order", {
	title = "High Order",
	sections = {
		{
			title = "Resumen",
			text = [=[La High Order agrupa a los magisters de los {link:skyborne}Skyborne{/link}, los descendientes de los eruditos Altonato de Eldre'Thalas. Se llaman a sí mismos los guardianes de las costumbres Altonato. En diez mil años en {link:skywall}Skywall{/link} olvidaron buena parte de su saber arcano, y su poder menguó. Se proponen recuperarlo.]=],
		},
		{
			title = "Su credo",
			text = [=[La High Order sostiene que los {link:skyborne}shen'dorei{/link} cometieron un grave error al poner su destino en manos de espíritus veleidosos. La desaparición de los espíritus lo demostró. Lo que antes hacían los espíritus, cree la orden, puede hacerse con la magia de los {red:highborne}Altonato{/red}, y la isla puede sostenerse por sí sola. Estudian las líneas ley surgidas en {link:zephras-isle}Zephras{/link} y la magia elemental de las piedras erguidas, digan lo que digan los {link:windshapers}Windshapers{/link}. Para los Windshapers son unos entrometidos. Para sí mismos son los únicos dispuestos a actuar.]=],
		},
		{
			title = "En el presente",
			text = [=[El Magister Supremo {link:elaadrin-evengale}Elaadrin Evengale{/link} halló la manera de asomarse a través de los planos, y encontró al {link:kirin-tor}Kirin Tor{/link} de {link:city-of-dalaran}Dalaran{/link} devolviéndole la mirada. Por medio del Kirin Tor, la High Order se ha unido a la {link:alliance}Alianza{/link}. Sus jóvenes magisters zarpan ahora de {link:valanaar}Valanaar{/link} rumbo a Dalaran para recuperar el saber que perdieron sus antepasados.]=],
		},
	},
})

Translate("esES", "al-aketh", {
	title = "Al'Aketh",
	aliases = { "culto Al'Aketh", "culto de Al'Akir" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Al'Aketh son un culto de {link:skyborne}shen'dorei{/link} que adoran a {link:al-akir}Al'Akir{/link}, el Señor del Viento. Algunos de sus fundadores usaron su vista celeste para mirar a través de {link:skywall}Skywall{/link} y vislumbraron el terrible poder de su amo. Tentados por ese poder, rompieron con su pueblo y se entregaron a su servicio. Cuando los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link} desaparecieron, el culto se alzó en el miedo que siguió.]=],
		},
		{
			title = "Su credo",
			text = [=[El culto predica que los {link:skyborne}shen'dorei{/link} se volvieron orgullosos y ociosos, dando por sentados los dones de los vientos, y que por eso los abandonaron los espíritus. Solo la penitencia y el servicio al {link:al-akir}Señor del Viento{/link} traerán de vuelta el viento. Sus misioneros fingen ser una fe amable. Sus matones, clamatormentas y asesinos hacen el resto. Muchos de sus miembros fueron antes {link:windshapers}Windshapers{/link}, {link:peacekeepers}Peacekeepers{/link} o druidas, y {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link} llama al culto un reflejo oscuro de su propia orden.]=],
		},
		{
			title = "En el presente",
			text = [=[Bajo la suma sacerdotisa {link:high-priestess-lorthuna}Lorthuna{/link}, el culto ocupó {link:falaath-village}Falaath Village{/link} y el {link:shrine-of-akir}Shrine of Akir{/link}, asaltó las caravanas de la isla y atacó las atalayas de los pilones para derribar las salvaguardas que ocultaban {link:zephras-isle}Zephras{/link}. Su suma sacerdotisa ha desaparecido y su santuario ha sido asaltado, pero su propósito se cumplió. Los servidores del {link:al-akir}Señor del Viento{/link} saben ahora dónde está Zephras.]=],
		},
	},
})

Translate("esES", "peacekeepers", {
	title = "Peacekeepers",
	aliases = { "Peacekeeper" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Peacekeepers son la milicia de {link:zephras-isle}Zephras Isle{/link} y lo más parecido a un ejército que tienen los {link:skyborne}Skyborne{/link}. Responden ante la capitana {link:valennia-stormfist}Valennia Stormfist{/link} en {link:valanaar}Valanaar{/link} y ante {link:shadow-council}el Consejo{/link} de Ancianos. Sus alguaciles mantienen el orden en los poblados, y sus soldados guarnecen las atalayas que guardan los {link:anchor-pylons}pilones de anclaje{/link}.]=],
		},
		{
			title = "En el presente",
			text = [=[Durante mucho tiempo los Peacekeepers evitaron la guerra abierta con los {link:al-aketh}Al'Aketh{/link}, con la esperanza de que el culto no pasara de ser una molestia. Esa esperanza terminó en {link:shen-dar-village}Shen'dar Village{/link} y en las atalayas de los pilones. Pocos en número, combatieron al culto por toda la isla y encabezaron el asalto al {link:shrine-of-akir}Shrine of Akir{/link}. También se interponen entre los {link:windshapers}Windshapers{/link} y la {link:high-order}High Order{/link}, y su capitana no tolera que las dos órdenes luchen en {link:valanaar}Valanaar{/link}. No todos permanecieron leales. {link:commander-belguilos}Belguilos{/link}, a quien el culto llama ahora la Quebrantadora, vistió en otro tiempo sus colores. Entre quienes resistieron estaban la alguacil {link:constable-aonda}Aonda{/link} de Shen'dar, la teniente {link:yorana-windyreed}Yorana Windyreed{/link} en la torre oriental y {link:hyusaa-quickbreeze}Hyusaa Quickbreeze{/link}, la segunda de la capitana.]=],
		},
	},
})

Translate("esES", "anchor-pylons", {
	title = "Pilones de anclaje",
	aliases = { "pilón de anclaje", "pilones de anclaje", "pilones del viento" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los pilones de anclaje son antiguas torres de magia elemental, dones de los {link:vanishing-of-the-wind-spirits}espíritus del viento{/link} a los {link:skyborne}shen'dorei{/link}. Mantienen unida {link:zephras-isle}Zephras Isle{/link} y la sujetan en su lugar en {link:skywall}Skywall{/link}. Junto a ellos se alzan atalayas de los {link:peacekeepers}Peacekeepers{/link}, una en las tierras altas del oeste y otra a las afueras de {link:valanaar}Valanaar{/link}.]=],
		},
		{
			title = "Su declive",
			text = [=[Desde que desaparecieron los espíritus, los pilones se han vuelto inestables. Su esplendor no ha cambiado, y no se ve ningún daño, pero su magia flaquea. A medida que se debilita, partes de la isla se desmoronan y caen hacia el cielo. Los {link:skyborne}shen'dorei{/link} recurren ahora a las piedras de viento para sus necesidades diarias, y la {link:high-order}High Order{/link} espera dominar la magia de los pilones antes de que falle del todo.]=],
		},
		{
			title = "Las salvaguardas",
			text = [=[Los {link:skyborne}shen'dorei{/link} casi habían olvidado un segundo propósito. Los pilones son también salvaguardas. Protegían la isla de la mirada de cualquier otra cosa que habitara en {link:skywall}Skywall{/link}. El {link:flight-from-eldre-thalas}Shal'nan{/link} habló de ello una vez, y los {link:al-aketh}Al'Aketh{/link} lo descubrieron. Atacaron los pilones para derribar las salvaguardas, y lo lograron. {link:zephras-isle}Zephras{/link} sigue flotando, pero ya no está oculta.]=],
		},
	},
})

Translate("esES", "vanishing-of-the-wind-spirits", {
	title = "La desaparición de los espíritus del viento",
	aliases = { "espíritus del viento" },
	sections = {
		{
			title = "Resumen",
			text = [=[Durante miles de años, los espíritus del viento vivieron en {link:zephras-isle}Zephras Isle{/link} junto a los {link:skyborne}shen'dorei{/link}, como protectores, maestros y amigos. Alzaron la isla, cuidaron su magia y dieron a sus videntes la vista celeste. Luego, hace varios siglos, desaparecieron. No dieron ningún aviso, y nadie en Zephras sabe por qué se fueron ni adónde.]=],
		},
		{
			title = "Lo que siguió",
			text = [=[La magia de la isla empezó a desvanecerse. Los {link:anchor-pylons}pilones de anclaje{/link} flaquearon. La mayoría de los ensamblajes de los espíritus dejaron de funcionar. Unos extraños espíritus pálidos llamados hollows aparecieron en el {link:shadowgale-forest}Shadowgale Forest{/link}. Las bestias se volvieron salvajes, y los espíritus menores del viento se volvieron violentos al ser perturbados. Se perdió el contacto con las otras islas, y aldeas enteras cayeron hacia el cielo. Cada facción interpretó la pérdida a su manera. Los {link:windshapers}Windshapers{/link} desean encontrar a los espíritus y llamarlos de vuelta. La {link:high-order}High Order{/link} dice que los elfos no deben volver a depender de ellos. Los {link:al-aketh}Al'Aketh{/link} predican que los espíritus abandonaron a un pueblo orgulloso, y que solo queda el {link:al-akir}Señor del Viento{/link}.]=],
		},
	},
})

Translate("esES", "flight-from-eldre-thalas", {
	title = "La huida de Eldre'Thalas",
	aliases = { "Rebelión en Eldre'Thalas", "Shal'nan" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los {link:skyborne}Skyborne{/link} empezaron como rebeldes. Tras la {link:war-of-the-ancients}Guerra de los Ancestros{/link}, los {red:highborne}Altonato{/red} de Eldre'Thalas, la ciudad de {link:feralas}Feralas{/link} que hoy se llama {red:dire-maul}La Masacre{/red}, quedaron sin el Pozo que había alimentado su magia. El príncipe {red:tortheldrin}Tortheldrin{/red} intentó sostenerlos con poderes cada vez más oscuros. Algunos de los suyos habían visto adónde llevaba esa ansia, y no permitirían que se repitieran los errores de {link:azshara}Azshara{/link}.]=],
		},
		{
			title = "El Velado",
			text = [=[Los rebeldes estaban dirigidos por una figura conocida solo como el Shal'nan, el Velado, que ocultaba el rostro tras una máscara de oro sin rasgos. Su nombre se convirtió en grito de guerra. Mediante sabotajes y cosas peores, sus seguidores entorpecieron la red de focos de cristal del príncipe y lo humillaron una y otra vez. En aquellos días el druidismo de los {link:night-elves}elfos de la noche{/link} del norte se extendió también por la ciudad, y el príncipe lo condenó como algo vil. Los rebeldes resistieron por última vez en su sanctasanctórum. Evitaron lo peor, pero la mayoría murió.]=],
		},
		{
			title = "La huida",
			text = [=[Los supervivientes huyeron al oeste con la flota del príncipe tras ellos. Más allá del mar encontraron una tierra gobernada por antiguos espíritus, y allí sellaron su pacto con el viento. Los espíritus alzaron la tierra hasta {link:skywall}Skywall{/link}, y los exiliados se convirtieron en los {link:skyborne}shen'dorei{/link}, el pueblo oculto. Con el tiempo, el Shal'nan renunció a su mando y lo entregó a un consejo elegido por su pueblo.]=],
		},
	},
})
